  v_route record;
  v_points jsonb;
  v_count integer;
  v_length_km double precision;
  v_max_gap_km double precision;
  v_center_gap_km double precision;
  v_start_gap_km double precision;
  v_end_gap_km double precision;
  v_invalid integer;
begin
  select h.id,h.latitude,h.longitude,h.distance_km,t.status
    into v_route
    from public.hiking_routes h
    join public.hiking_route_tracks t on t.route_id=h.id
    where h.id='osm-relation-17461791'
      and h.source='openstreetmap'
      and h.route_ref='PR-CV 444'
      and h.official_url='https://senders.femecv.com/es/sendero/ver/pr-cv-444'
      and exists (select 1 from public.hiking_route_regions r
        where r.route_id=h.id and r.published);
  if not found then
    raise exception 'PR-CV 444 identity or published region changed';
  end if;
  if v_route.status='ready' then
    return;
  end if;
  with points as (
    select ordinality idx,(point->>0)::double precision lat,
      (point->>1)::double precision lon
    from jsonb_array_elements(v_coords) with ordinality as p(point,ordinality)
  ), steps as (
    select *,lag(lat) over(order by idx) prev_lat,
      lag(lon) over(order by idx) prev_lon from points
  ), distances as (
    select case when prev_lat is null then 0 else 6371*2*asin(sqrt(
      least(1,power(sin(radians(lat-prev_lat)/2),2)+
      cos(radians(prev_lat))*cos(radians(lat))*
      power(sin(radians(lon-prev_lon)/2),2)))) end step_km,
      6371*2*asin(sqrt(least(1,
      power(sin(radians(lat-v_route.latitude)/2),2)+
      cos(radians(v_route.latitude))*cos(radians(lat))*
      power(sin(radians(lon-v_route.longitude)/2),2)))) center_km,
      (lat between 27 and 45 and lon between -19 and 5) valid
    from steps
  ) select count(*),coalesce(sum(step_km),0),coalesce(max(step_km),0),
      coalesce(min(center_km),999),count(*) filter(where not valid)
    into v_count,v_length_km,v_max_gap_km,v_center_gap_km,v_invalid
    from distances;
  -- Validate the endpoints against the start and finish pins linked by FEMECV.
  v_start_gap_km := 6371*2*asin(sqrt(least(1,
    power(sin(radians(((v_coords->0->>0)::double precision-38.350350)/2)),2)+
    cos(radians(38.350350))*cos(radians((v_coords->0->>0)::double precision))*
    power(sin(radians(((v_coords->0->>1)::double precision+0.856494)/2)),2))));
  v_end_gap_km := 6371*2*asin(sqrt(least(1,
    power(sin(radians(((v_coords->(jsonb_array_length(v_coords)-1)->>0)::double precision-38.353369)/2)),2)+
    cos(radians(38.353369))*cos(radians((v_coords->(jsonb_array_length(v_coords)-1)->>0)::double precision))*
    power(sin(radians(((v_coords->(jsonb_array_length(v_coords)-1)->>1)::double precision+0.734074)/2)),2))));
  if v_count<>1190 or v_invalid>0 or v_length_km<=0
    or v_max_gap_km>0.30 or v_center_gap_km>2
    or v_start_gap_km>0.10 or v_end_gap_km>0.10
    or abs(v_length_km/14.6-1)>0.10
    or (v_route.distance_km is not null
      and abs(v_length_km/v_route.distance_km-1)>0.12) then
    raise exception 'PR-CV 444 GPS geometry failed: points %, length %, gap %, center %, invalid %',
      v_count,v_length_km,v_max_gap_km,v_center_gap_km,v_invalid;
  end if;
  select jsonb_agg(jsonb_build_object('lat',(point->>0)::double precision,
    'lon',(point->>1)::double precision) order by ordinality)
    into v_points from jsonb_array_elements(v_coords)
      with ordinality as p(point,ordinality);
  insert into public.hiking_route_tracks
    (route_id,status,segments,checked_at,continuity_checked,
     geometry_source,geometry_source_url,official)
  values ('osm-relation-17461791','ready',jsonb_build_array(v_points),
    now(),true,
    'Federación de Deportes de Montaña y Escalada de la Comunitat Valenciana (FEMECV)',
    'https://femecv.blob.core.windows.net/publico/gpx/TRACKPRCV444.gpx',true)
  on conflict(route_id) do update set
    status=excluded.status,segments=excluded.segments,
    checked_at=excluded.checked_at,continuity_checked=true,
    geometry_source=excluded.geometry_source,
    geometry_source_url=excluded.geometry_source_url,official=true;
  update public.hiking_routes
    set trace_available=true,published=true,distance_km=coalesce(distance_km,14.6)
    where id='osm-relation-17461791';
end
$curate$;
